            //             "maintenance_margin_rate": "0.005",
            //             "maintenance_margin_value": "0.03051465",
            //             "margin_avbl": "3.034928",
            //             "margin_mode": "isolated",
            //             "market": "BTCUSDT",
            //             "market_type": "FUTURES",
            //             "max_position_value": "6.104784",
            //             "open_interest": "0.0001",
            //             "position_id": 306458800,
